'use client';
import type { ImageLoaderProps } from 'next/image';
import heroImages from './hero-images.json';
import galleryImages from './gallery-images.json';

const optimized = new Set(['new-york', 'networking', 'heidy-hernandez-president-dominican-usa-chamber-of-commerce', ...galleryImages.map(({ name }) => name), ...heroImages.map(({ name }) => `hero-${name}`)]);
// Widths generated by scripts/optimize-images.mjs (deviceSizes + imageSizes in next.config.ts).
const widths = [96, 160, 256, 384, 480, 768, 1200, 1600];
const pick = (width: number) => widths.find(size => size >= width) || 1600;
const INFOTEP_LOGO = "/imgs/INFOTEP logos's.png";

export default function imageLoader({ src, width }: ImageLoaderProps): string {
  if (src === INFOTEP_LOGO) return `/imgs/infotep-logo-${pick(width)}.webp`;
  const match = /^\/assets\/([a-z-]+)\.jpg$/.exec(src);
  if (!match || !optimized.has(match[1])) return src;
  return `/assets/${match[1]}-${pick(width)}.webp`;
}
